{
  "description": "The creature is shown in right-facing side profile against a plain light background, with the overall body shape, fur, and proportions of a brown bear but with glossy beetle-like exoskeleton elements integrated into its surface. The body is covered in dense, shaggy brown fur that is darker on the back and legs and lighter tan on the muzzle, chest, and underside. It stands on four thick legs ending in broad clawed paws and has a short furry tail at the rear. A single large, curved, glossy black horn projects from the forehead, and multiple hard, shiny dark brown and black plates resembling beetle elytra and pronotum are embedded along the back, sides, shoulders, throat, and around the leg joints. A row of small oval openings with dark rims is visible along the lower flank and on the throat.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, on the right end of the body facing right, covered in brown fur with a lighter tan muzzle, a black nose at the tip, a small dark brown eye, and a closed mouth with a hint of the lower lip visible"
    ,
      "where": "at the front right of the body, connected to the neck"
    },
    {
      "part": "horns",
      "looks_like": "one large glossy black horn, smooth and curved upward and forward with two small pointed prongs on the inner curve near the tip and a bulbous base where it meets the fur",
      "where": "rising from the center of the forehead just in front of and between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in dense brown fur, slightly darker at the edges",
      "where": "on top of the head behind the horn, one slightly in front of the other in side view"
    },
    {
      "part": "legs",
      "looks_like": "four thick columnar legs covered in long shaggy brown fur, each with a glossy dark brown jointed plate encircling the upper joint and a smaller plate near the lower joint/ankle",
      "where": "extending downward from the underside of the torso, two forelegs under the chest and two hind legs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with brown fur on top and five long, curved, light tan claws protruding forward from each paw, with visible paw pads underneath",
      "where": "at the bottom ends of the four legs resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a small short tuft of brown fur, slightly darker and shaggy",
      "where": "protruding from the rear left end of the body above the hind legs"
    },
    {
      "part": "plates",
      "looks_like": "multiple hard, glossy, smooth plates in dark brown to black, resembling beetle exoskeleton; includes a large ridged oval plate with a central seam and a pointed rear extension on the mid-side, smaller irregular triangular and oval plates along the back and rump, a large black and brown shield-like plate with visible suture lines on the shoulders/upper back, and smaller glossy plates on the throat and encircling the leg joints",
      "where": "embedded in the fur along the dorsal midline, rump, mid-flank, shoulder, throat, and around the leg joints"
    },
    {
      "part": "markings",
      "looks_like": "a row of five small oval openings with dark rims and light centers, resembling spiracles, set in lighter fur, plus several similar smaller openings on the lower neck and chest",
      "where": "along the lower side of the torso just below the large side plate, and on the throat/chest below the shoulder plate"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
